    public ReconcileReport reconcile(List<Map<String, Object>> desired) {
        Map<String, Map<String, Object>> byName = new LinkedHashMap<>();
        for (Map<String, Object> policy : client.listPolicies()) {
            if (policy.get("name") instanceof String name) {
                byName.putIfAbsent(name, policy);
            }
        }
        List<String> created = new ArrayList<>();
        List<String> edited = new ArrayList<>();
        List<String> skipped = new ArrayList<>();
        Map<String, DbxApiException> failures = new LinkedHashMap<>();
        for (Map<String, Object> want : desired) {
            String name = (String) want.get("name");
            Map<String, Object> existing = byName.get(name);
            try {
                if (existing == null) {
                    client.createPolicy(payload(name, want, null));
                    created.add(name);
                } else if (inSync(want, existing)) {
                    skipped.add(name);
                } else if (Boolean.TRUE.equals(existing.get("is_default"))) {
                    throw new DbxApiException(0, "IS_DEFAULT_POLICY",
                            "policy '" + name + "' is a Databricks-managed default policy and must not be edited");
                } else {
                    Map<String, Object> fields = payload(name, want, existing);
                    fields.put("policy_id", existing.get("policy_id"));
                    client.editPolicy(fields);
                    edited.add(name);
                }
            } catch (DbxApiException e) {
                failures.put(name, e);
            }
        }
        return new ReconcileReport(created, edited, skipped, failures);
    }

